import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"Set up local development","description":"Install each independent repository, start shared infrastructure from the deployment repository, and verify local changes in layers.","frontmatter":{"page_id":"development-local-setup","title":"Set up local development","description":"Install each independent repository, start shared infrastructure from the deployment repository, and verify local changes in layers."},"headers":[],"relativePath":"en/development/local-setup.md","filePath":"en/development/local-setup.md","lastUpdated":1786627803000}'),t={name:"en/development/local-setup.md"};function l(p,s,r,h,o,d){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="set-up-local-development" tabindex="-1">Set up local development <a class="header-anchor" href="#set-up-local-development" aria-label="Permalink to &quot;Set up local development&quot;">​</a></h1><p>Ershu components are maintained independently. When changing one component, install, test, and build it in its own repository. Use the <code>ershu</code> deployment repository when you need shared infrastructure and a pinned backend composition for integration work.</p><h2 id="what-to-install" tabindex="-1">What to install <a class="header-anchor" href="#what-to-install" aria-label="Permalink to &quot;What to install&quot;">​</a></h2><ul><li>Python 3.14 and UV.</li><li>Node.js 24 and npm.</li><li>Docker with Compose v2.</li><li>Git.</li><li>The Ershu repositories involved in the change.</li></ul><p>Keep repositories as siblings:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/</span></span>
<span class="line"><span>├── ershu/</span></span>
<span class="line"><span>├── ershu-core/</span></span>
<span class="line"><span>├── ershu-api/</span></span>
<span class="line"><span>├── ershu-worker/</span></span>
<span class="line"><span>├── ershu-mcp/</span></span>
<span class="line"><span>├── frontend/</span></span>
<span class="line"><span>└── ershu-docs/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>They are not one monorepo. Each directory has its own version, lock file, tests, and release. Do not commit changes for one repository from another repository.</p><h2 id="work-on-one-backend-component" tabindex="-1">Work on one backend component <a class="header-anchor" href="#work-on-one-backend-component" aria-label="Permalink to &quot;Work on one backend component&quot;">​</a></h2><p>Enter the target repository and install from its lock file:</p><table tabindex="0"><thead><tr><th>Repository</th><th>Install</th><th>Minimum check</th></tr></thead><tbody><tr><td><code>ershu-core</code></td><td><code>uv sync --locked</code></td><td><code>uv run pytest -m &quot;not integration&quot;</code></td></tr><tr><td><code>ershu-api</code></td><td><code>uv sync --locked --extra dev</code></td><td><code>uv run --extra dev pytest -q</code></td></tr><tr><td><code>ershu-worker</code></td><td><code>uv sync --locked --extra dev</code></td><td><code>uv run pytest -q</code></td></tr><tr><td><code>ershu-mcp</code></td><td><code>uv sync --locked</code></td><td><code>uv run pytest -q</code></td></tr></tbody></table><p>API, Worker, and MCP declare the Core version ranges they support, while each lock file records the version selected for that development environment. When a Core change affects public behavior, test the affected consumers too. Matching component version numbers are not a compatibility test.</p><h2 id="start-shared-infrastructure" tabindex="-1">Start shared infrastructure <a class="header-anchor" href="#start-shared-infrastructure" aria-label="Permalink to &quot;Start shared infrastructure&quot;">​</a></h2><p>Copy the examples in the <code>ershu</code> deployment repository:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Replace passwords and secrets in both files, then start the infrastructure:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.infrastructure.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.infrastructure.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Inspect a service when needed:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.infrastructure.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=200</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">service-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This starts PostgreSQL, Redis, Milvus, etcd, and MinIO. Stop the containers without deleting their data when development ends:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.infrastructure.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="start-a-pinned-backend-composition" tabindex="-1">Start a pinned backend composition <a class="header-anchor" href="#start-a-pinned-backend-composition" aria-label="Permalink to &quot;Start a pinned backend composition&quot;">​</a></h2><p>From a published deployment tag, run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Then start the processes separately:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal B</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-worker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal C</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-mcp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal D, only for scheduled polling</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>When developing one component, stop its process from the deployment environment and run that component from its own repository instead. Both processes must use the same <code>DATABASE_URL</code>, Milvus address, and encryption secrets.</p><h2 id="start-the-frontend" tabindex="-1">Start the frontend <a class="header-anchor" href="#start-the-frontend" aria-label="Permalink to &quot;Start the frontend&quot;">​</a></h2><p>In the <code>frontend</code> repository:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The Chinese entry point is <code>http://localhost:3000/#/zh</code>, and English is <code>http://localhost:3000/#/en</code>. The development proxy sends <code>/api</code> to API on port <code>8000</code> and <code>/mcp</code> to MCP on port <code>8001</code> by default.</p><h2 id="what-a-useful-local-environment-looks-like" tabindex="-1">What a useful local environment looks like <a class="header-anchor" href="#what-a-useful-local-environment-looks-like" aria-label="Permalink to &quot;What a useful local environment looks like&quot;">​</a></h2><p>Check in order:</p><ol><li>PostgreSQL, Redis, and Milvus pass their Compose health checks.</li><li><code>ershu-db current</code> matches <code>ershu-db heads</code>.</li><li>API and MCP return <code>ok</code> from <code>/health</code>.</li><li>The frontend opens the administrator setup or sign-in page.</li><li>An administrator can create and test model channels.</li><li>The Worker claims a full-project run instead of leaving it in <code>queued</code>.</li><li>After the run, the wiki opens, source search works, and citations lead back to repositories.</li></ol><p>Stop at the first failed layer. If API is live but a run does not move, inspect Worker first. If document generation fails, check the language-model channel. If semantic retrieval fails, check Milvus, the embedding channel, and the search-index status.</p>`,34)])])}const u=e(t,[["render",l]]);export{k as __pageData,u as default};
